let transfer={phase:'',time:0,done:0};
window.aguja.onProgress(p=>{$('cancel-download').hidden=!p.cancellable;$('cancel-download').disabled=false;$('progress').hidden=false;const captions={download:t('Descargando la imagen oficial…'),verify:t('Comprobando SHA-256…'),prepare:(p.message?t(p.message):null)||t('Preparando tu imagen privada…'),flash:(p.message?t(p.message):null)||t('Respaldando y grabando…'),'iot-flash':(p.message?t(p.message):null)||t('Grabando microcontrolador…')};$('progress-message').textContent=captions[p.phase]||t('Trabajando…');if(p.phase==='iot-flash'){appendIotLog((p.stage?`[${p.stage}] `:'')+(p.message||''));}if(p.phase==='iot-flash'&&p.total===100){$('progress-bar').max=100;$('progress-bar').value=p.done||0;$('progress-count').textContent=Math.floor(p.done||0)+'%';}else if(p.total){$('progress-bar').max=p.total;$('progress-bar').value=p.done||0;const now=Date.now();if(transfer.phase!==p.phase||p.done<transfer.done)transfer={phase:p.phase,time:now,done:p.done||0};const seconds=(now-transfer.time)/1000,rate=seconds>1?((p.done||0)-transfer.done)/seconds:0,eta=rate>0?Math.ceil((p.total-(p.done||0))/rate):0;$('progress-count').textContent=Math.floor(100*(p.done||0)/p.total)+'% · '+fmt(p.done||0)+' / '+fmt(p.total)+(rate>0?' · '+(rate/1048576).toFixed(1)+' MiB/s · ~'+Math.ceil(eta/60)+' min':'');}else{$('progress-bar').removeAttribute('value');$('progress-count').textContent='';}});
