function applyProviderState(){for(const [id,p]of Object.entries(providerState)){$('badge-'+id).textContent=p.imported?t('Importación preparada'):p.installed?t('CLI local disponible'):t('CLI no instalado');$('badge-'+id).className=p.installed||p.imported?'badge':'badge missing';$('install-'+id).hidden=p.installed;$('install-'+id).disabled=busy;$('login-'+id).disabled=busy||!p.installed;}}
