function selectedIotBoard(){return iotBoards.find(b=>b.id===iotSelectedBoardId)||null;}
function appendIotLog(line){const pre=$('iot-live-log'),card=$('iot-log-card');if(!pre||!line)return;if(card)card.hidden=false;const ts=new Date().toTimeString().slice(0,8);pre.textContent+=(pre.textContent?'\n':'')+`[${ts}] ${line}`;pre.scrollTop=pre.scrollHeight;}
function setIotProvider(next){iotProvider=next==='headscale'?'headscale':'tailscale';$('iot-provider-tailscale')?.classList.toggle('active',iotProvider==='tailscale');$('iot-provider-tailscale')?.setAttribute('aria-pressed',String(iotProvider==='tailscale'));$('iot-provider-headscale')?.classList.toggle('active',iotProvider==='headscale');$('iot-provider-headscale')?.setAttribute('aria-pressed',String(iotProvider==='headscale'));if($('iot-headscale-fields'))$('iot-headscale-fields').hidden=iotProvider!=='headscale';if(!iotDerpEdited&&$('iot-derp-region'))$('iot-derp-region').value=iotProvider==='headscale'?'999':'9';updateIotSummary();updateIotFlashState();}
function syncIotSoftApDeps(){const on=Boolean($('iot-ap-enabled')?.checked);if($('iot-ap-fields'))$('iot-ap-fields').hidden=!on;if($('iot-sub-ap')){$('iot-sub-ap').disabled=!on||busy;if(!on)$('iot-sub-ap').checked=false;}if($('iot-sub-ap-hint'))$('iot-sub-ap-hint').textContent=t(on?'Permite alcanzar dispositivos conectados al SoftAP del microcontrolador desde tu tailnet.':'Activa primero el SoftAP en el paso 02 si quieres enrutar clientes conectados a su Wi-Fi.');}
function iotPrimaryWifi(){return {ssid:($('iot-wifi-ssid')?.value||'').trim(),password:$('iot-wifi-password')?.value||''};}
function iotWifiRows(){if(!$('iot-wifi-ssid'))return [];const extras=[...($('iot-wifi-extra-entries')?.children||[])].map(row=>({ssid:row.querySelector('.iot-wifi-ssid').value.trim(),password:row.querySelector('.iot-wifi-password').value}));return [iotPrimaryWifi(),...extras].filter(w=>w.ssid);}
function fillIotWifi(rows){if(!$('iot-wifi-ssid'))return;const first=rows[0]||{};$('iot-wifi-ssid').value=first.ssid||'';$('iot-wifi-password').value=first.password||'';$('iot-wifi-extra-entries').replaceChildren();for(const r of rows.slice(1))addIotWifi(r);updateIotSummary();updateIotFlashState();}
function addIotWifi(value={}){if(!$('iot-wifi-extra-entries'))return;if($('iot-wifi-extra-entries').children.length>=7){notice(t('Añade como máximo 8 redes Wi-Fi para el microcontrolador.'));return;}const id='iot-wifi-extra-'+(++extraSequence),row=document.createElement('div');row.className='wifi-entry';row.innerHTML=`<div class="entry-heading"><h3>Otra red Wi-Fi</h3><div class="button-row"><button type="button" class="quiet iot-wifi-up" aria-label="Subir prioridad">↑</button><button type="button" class="quiet iot-wifi-remove">Quitar</button></div></div><label for="${id}-ssid">Nombre de la red (SSID · 2.4 GHz)</label><input id="${id}-ssid" class="iot-wifi-ssid" maxlength="32" autocomplete="off"><label for="${id}-password">Contraseña</label><div class="secret"><input id="${id}-password" class="iot-wifi-password" type="password" maxlength="64" autocomplete="new-password"><button type="button" class="reveal" data-for="${id}-password" aria-label="Mostrar contraseña Wi-Fi">◉</button></div>`;I18n.translateTree(row);$('iot-wifi-extra-entries').append(row);row.querySelector('.iot-wifi-ssid').value=value.ssid||'';row.querySelector('.iot-wifi-password').value=value.password||'';row.querySelector('.iot-wifi-remove').addEventListener('click',()=>{row.remove();updateIotSummary();updateIotFlashState();});row.querySelector('.iot-wifi-up').addEventListener('click',()=>{const all=[iotPrimaryWifi(),...[...$('iot-wifi-extra-entries').children].map(el=>({ssid:el.querySelector('.iot-wifi-ssid').value,password:el.querySelector('.iot-wifi-password').value}))];const idx=[...$('iot-wifi-extra-entries').children].indexOf(row)+1;[all[idx-1],all[idx]]=[all[idx],all[idx-1]];fillIotWifi(all);});}
function iotConfigPayload(){const apOn=Boolean($('iot-ap-enabled')?.checked);return {wifiProfiles:iotWifiRows(),ap:{enabled:apOn,ssid:($('iot-ap-ssid')?.value||'Aguja-IoT-AP').trim(),password:$('iot-ap-password')?.value||'',channel:Number($('iot-ap-channel')?.value||6)},tailnet:{hostname:($('iot-hostname')?.value||'aguja-iot').trim(),ctrlHost:iotProvider==='headscale'?($('iot-ctrl-host')?.value||'').trim():'controlplane.tailscale.com',ctrlNoisePubkeyHex:iotProvider==='headscale'?($('iot-noise-key')?.value||'').trim():'',authKey:($('iot-auth-key')?.value||'').trim(),derpRegion:Number($('iot-derp-region')?.value||(iotProvider==='headscale'?999:9)),exitNodeEnabled:Boolean($('iot-exit-node')?.checked),advertiseUpstreamSubnet:Boolean($('iot-sub-upstream')?.checked),advertiseApSubnet:apOn&&Boolean($('iot-sub-ap')?.checked),dnsRelayEnabled:Boolean($('iot-dns-relay')?.checked),dnsUpstream:($('iot-dns-upstream')?.value||'1.1.1.1').trim(),extraRoutes:($('iot-extra-routes')?.value||'').trim()},hw:{antennaExternal:$('iot-antenna')?.value==='external'},agent:{apiToken:($('iot-api-token')?.value||'').trim(),httpAllowLan:Boolean($('iot-http-lan')?.checked),beaconEnabled:Boolean($('iot-beacon-enabled')?.checked),beaconIp:($('iot-beacon-ip')?.value||'').trim(),beaconPort:Number($('iot-beacon-port')?.value||9420)}};}
function renderIotFamilyFilters(){const bar=$('iot-family-filters');if(!bar)return;const items=[{id:'ALL',label:t('Todas')+' ('+iotBoards.length+')'},...iotFamilies.map(f=>({id:f,label:f+' ('+iotBoards.filter(b=>b.family===f).length+')'}))];bar.replaceChildren(...items.map(it=>{const b=document.createElement('button');b.type='button';b.className='chip'+(iotFamilyFilter===it.id?' active':'');b.textContent=it.label;b.addEventListener('click',()=>{iotFamilyFilter=it.id;renderIotFamilyFilters();renderIotBoards();});return b;}));}
function renderIotBoards(){const grid=$('iot-board-grid');if(!grid)return;grid.replaceChildren();const q=iotBoardQuery.trim().toLowerCase();const filtered=iotBoards.filter(b=>{if(iotFamilyFilter!=='ALL'&&b.family!==iotFamilyFilter)return false;if(!q)return true;const hay=`${b.name} ${b.chip} ${b.family||''} ${b.short_desc||''} ${(b.radios||[]).join(' ')}`.toLowerCase();return hay.includes(q);});for(const board of filtered){const planned=board.status==='planned';const btn=document.createElement('button');btn.type='button';btn.className='board-card'+(board.id===iotSelectedBoardId?' selected':'')+(planned?' planned':'');btn.dataset.boardId=board.id;btn.disabled=planned||busy;btn.setAttribute('role','radio');btn.setAttribute('aria-checked',String(board.id===iotSelectedBoardId));const head=document.createElement('div');head.className='board-card-head';const title=document.createElement('strong');title.textContent=board.name;const badge=document.createElement('span');badge.className='badge'+(planned||!board.firmwareReady?' missing':'');const isDetected=iotDetected?.matchedBoardId===board.id;badge.textContent=isDetected?'★ '+t('Detectada'):planned?t('Próximamente'):board.firmwareReady?('v'+(board.firmwareVersion||'1.4.0')):t('Sin firmware');head.append(title,badge);const desc=document.createElement('p');desc.className='hint';desc.textContent=board.short_desc||'';const specs=document.createElement('div');specs.className='board-specs';const pills=[board.chip.toUpperCase(),board.flash_size+' Flash',board.psram_mb?board.psram_mb+' MB PSRAM':board.sram_kb+' KB SRAM',board.cpu_mhz?board.cpu_mhz+' MHz':'',...(board.radios||[]).slice(0,2)].filter(Boolean);for(const label of pills){const pill=document.createElement('span');pill.className='board-pill';pill.textContent=label;specs.append(pill);}btn.append(head,desc,specs);if(!planned)btn.addEventListener('click',()=>{iotSelectedBoardId=board.id;renderIotBoards();updateIotBoardDetails();updateIotSummary();updateIotFlashState();});grid.append(btn);}if(!filtered.length){const empty=document.createElement('p');empty.className='soft-note';empty.textContent=t('No hay placas que coincidan con ese filtro.');grid.append(empty);}updateIotBoardDetails();}
function renderIotFlashMap(){const tbody=$('iot-flash-map-body');if(!tbody)return;const b=selectedIotBoard();const segs=b?.firmwareSegments||[];tbody.replaceChildren(...segs.map(s=>{const tr=document.createElement('tr');const kb=s.bytes>=1024*1024?(s.bytes/1048576).toFixed(2)+' MB':Math.round(s.bytes/1024)+' KB';for(const text of [s.offset,s.name,kb,s.sha256Short||'—']){const td=document.createElement('td');td.textContent=text;tr.append(td);}return tr;}));}
function updateIotBoardDetails(){const b=selectedIotBoard();if($('iot-xiao-hw-card'))$('iot-xiao-hw-card').hidden=!b?.has_rf_switch;renderIotFlashMap();if(!$('iot-fw-badge'))return;if(!b){$('iot-fw-badge').textContent=t('Sin placa');$('iot-fw-badge').className='badge missing';$('iot-fw-status').textContent=t('Selecciona una placa para comprobar su firmware precompilado.');return;}if(b.firmwareReady){$('iot-fw-badge').textContent='v'+(b.firmwareVersion||'1.4.0')+' · '+t('Integrado y listo');$('iot-fw-badge').className='badge';$('iot-fw-status').textContent=t('Firmware genérico integrado listo para grabar (Dual-OTA + NVS v2 + SHA-256 verificado). No requiere compiladores.');}else{$('iot-fw-badge').textContent=t('Falta firmware');$('iot-fw-badge').className='badge missing';$('iot-fw-status').textContent=t('No se encontró firmware compilado para este perfil. Compílalo con iot/scripts/build-firmware.sh o carga una carpeta local.');}}
function applyDetectedHardware(det){iotDetected=det||null;const st=$('iot-detect-status'),meta=$('iot-detect-meta');if(!st||!meta)return;if(!det){meta.hidden=true;return;}st.textContent=det.matchedBoardName?`✓ ${t('Placa detectada automáticamente')}: ${det.matchedBoardName} ${t('en')} ${det.port}`:`✓ ${t('Chip detectado')}: ${det.chip} ${t('en')} ${det.port}`;const pills=[det.chip,det.flashSize?'Flash '+det.flashSize:'',det.psramMb?'PSRAM '+det.psramMb+' MB':'Sin PSRAM',det.mac?'MAC '+det.mac:'',det.port,det.usbId?'USB '+det.usbId:''].filter(Boolean);meta.replaceChildren(...pills.map(p=>{const sp=document.createElement('span');sp.className='board-pill';sp.textContent=p;return sp;}));meta.hidden=false;if(det.matchedBoardId&&iotBoards.some(b=>b.id===det.matchedBoardId)){iotSelectedBoardId=det.matchedBoardId;iotFamilyFilter='ALL';renderIotFamilyFilters();renderIotBoards();}if(det.port&&$('iot-port')){if(![...$('iot-port').options].some(o=>o.value===det.port)){const opt=document.createElement('option');opt.value=det.port;opt.textContent=`${det.port} · ${det.chip} ★ ${t('Detectada')}`;$('iot-port').append(opt);}$('iot-port').value=det.port;}updateIotSummary();updateIotFlashState();}
async function runIotAutoDetect({silent=false}={}){if(!window.aguja.iotDetect)return;if(silent){try{const r=await window.aguja.iotPorts?.();if(!r?.ok||!r.ports?.some(p=>p.accessible))return;}catch{return;}}const r=await call('iotDetect');if(!r)return;if(r.ports){iotPorts=r.ports;populateIotPortsSelect(r.ports,r.detected?.port||'');}if(r.detected){applyDetectedHardware(r.detected);if(!silent)notice(t('Placa detectada automáticamente: ')+(r.detected.matchedBoardName||r.detected.chip)+' ('+r.detected.port+').',true);}else if(!silent){notice(r.warning||t('No se detectó ninguna placa ESP32 conectada por USB. Conéctala y vuelve a intentarlo.'));}}
function populateIotPortsSelect(ports,preferred=''){if(!$('iot-port'))return;const prev=preferred||$('iot-port').value;$('iot-port').replaceChildren();const blank=document.createElement('option');blank.value='';blank.textContent=ports.length?t('Elige un puerto USB serie'):t('No se detectaron placas USB serie');$('iot-port').append(blank);let autoPick='';for(const p of ports){const opt=document.createElement('option');opt.value=p.path;const matched=iotSelectedBoardId&&p.matchedBoardIds?.includes(iotSelectedBoardId);const tag=iotDetected?.port===p.path?' ★ '+t('Detectada'):matched?' ★ '+t('Compatible'):'';const perm=p.accessible?'':' ('+t('sin permisos')+')';opt.textContent=`${p.path} · ${p.product}${p.usbId?' ['+p.usbId+']':''}${tag}${perm}`;$('iot-port').append(opt);if(!autoPick&&(iotDetected?.port===p.path||matched)&&p.accessible)autoPick=p.path;}if(prev&&ports.some(p=>p.path===prev))$('iot-port').value=prev;else if(autoPick)$('iot-port').value=autoPick;else if(ports.length===1&&ports[0].accessible)$('iot-port').value=ports[0].path;updateIotFlashState();}
async function refreshIotBoards(){if(!window.aguja.iotBoards)return;try{const r=await window.aguja.iotBoards();if(!r?.ok)return;iotAvailable=r.available!==false;iotBoards=r.boards||[];iotFamilies=r.families||[...new Set(iotBoards.map(b=>b.family).filter(Boolean))];if($('iot-platform-banner'))$('iot-platform-banner').hidden=iotAvailable;if(!iotSelectedBoardId||!iotBoards.some(b=>b.id===iotSelectedBoardId&&b.status!=='planned')){const preferred=iotBoards.find(b=>b.status!=='planned'&&b.firmwareReady)||iotBoards.find(b=>b.status!=='planned');iotSelectedBoardId=preferred?.id||'';}renderIotFamilyFilters();renderIotBoards();updateIotSummary();updateIotFlashState();await refreshIotPorts();}catch{}}
async function ensureIotToken(){if(!$('iot-api-token')||$('iot-api-token').value.trim()||!window.aguja.iotGenerateToken)return;try{const r=await window.aguja.iotGenerateToken();if(r?.ok&&r.token)$('iot-api-token').value=r.token;}catch{}}
async function refreshIotPorts(){if(!window.aguja.iotPorts||!$('iot-port'))return;try{const r=await window.aguja.iotPorts();if(!r?.ok)return;iotPorts=r.ports||[];populateIotPortsSelect(iotPorts);}catch{}}
function updateIotSummary(){const dl=$('iot-summary');if(!dl)return;const b=selectedIotBoard(),cfg=iotConfigPayload();const proxyRoles=[cfg.tailnet.exitNodeEnabled?'Exit Node':null,cfg.tailnet.advertiseUpstreamSubnet?'Subnet Wi-Fi':null,cfg.tailnet.advertiseApSubnet?'Subnet SoftAP':null,cfg.tailnet.dnsRelayEnabled?'DNS Relay':null].filter(Boolean).join(' · ')||t('Solo cliente');const rows=[[t('Placa'),b?b.name+' ('+b.chip.toUpperCase()+')':t('Pendiente')],[t('Firmware'),b?.firmwareReady?'v'+(b.firmwareVersion||'1.4.0')+' · SHA-256':t('Pendiente')],[t('Redes Wi-Fi'),cfg.wifiProfiles.length?cfg.wifiProfiles.map(w=>w.ssid).join(', '):t('Pendiente')],[t('Punto de acceso SoftAP'),cfg.ap.enabled?cfg.ap.ssid+' (ch '+cfg.ap.channel+')':t('Desactivado')],[t('Proveedor / Nodo'),(iotProvider==='headscale'?'Headscale':'Tailscale')+' · '+cfg.tailnet.hostname],[t('Servidor / DERP'),(cfg.tailnet.ctrlHost||'controlplane.tailscale.com')+' · DERP '+cfg.tailnet.derpRegion],[t('Modo proxy'),proxyRoles],[t('Token agente'),cfg.agent.apiToken?t('Configurado (privado)'):t('Se generará al grabar')]];dl.replaceChildren(...rows.map(([k,v])=>{const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;div.append(dt,dd);return div;}));}
function updateIotFlashState(){const btn=$('iot-flash-btn'),st=$('iot-flash-status'),eraseBtn=$('iot-erase-btn'),probeBtn=$('iot-probe-port-btn');if(!btn||!st)return;const b=selectedIotBoard(),wifiCount=iotWifiRows().length,authKey=($('iot-auth-key')?.value||'').trim(),portPath=$('iot-port')?.value||'';const portObj=iotPorts.find(p=>p.path===portPath);const portReady=iotAvailable&&!busy&&Boolean(portPath)&&(!portObj||portObj.accessible);if(eraseBtn)eraseBtn.disabled=!portReady;if(probeBtn)probeBtn.disabled=!portReady;const ready=portReady&&Boolean(b?.firmwareReady)&&wifiCount>0&&Boolean(authKey);btn.disabled=!ready;st.textContent=!iotAvailable?t('La grabación IoT está disponible primero en Linux.'):busy?t('Espera a que termine la operación actual.'):!b?t('Selecciona una placa de desarrollo en el paso 01.'):!b.firmwareReady?t('Falta el paquete de firmware compilado para esta placa.'):!wifiCount?t('Añade al menos una red Wi-Fi en el paso 02.'):!authKey?t('Introduce la clave de alta Tailscale / Headscale en el paso 03.'):!portPath?t('Conecta la placa por USB y pulsa «Buscar puertos» o «Detectar placa conectada».'):portObj&&!portObj.accessible?t('Sin permisos en el puerto seleccionado. Añade tu usuario al grupo uucp/dialout.'):t('Todo listo para generar la partición NVS privada y grabar ')+b.name+t(' en ')+portPath+'.';}
function renderIotResult(r){const card=$('iot-result-card');if(!card)return;iotLastResult=r;card.hidden=false;const boot=r.boot||{};const badge=$('iot-result-badge');badge.textContent=boot.vpn_ip?t('En línea · ')+boot.vpn_ip:boot.wifi_ip?t('Wi-Fi listo · ')+boot.wifi_ip:t('Grabado');badge.className='badge';const rows=[[t('Placa'),r.boardName+' ('+r.chip+')'],[t('Puerto / MAC'),r.port+(r.mac?' · '+r.mac:'')],[t('Firmware'),r.firmwareVersion+(r.flashSize?' · Flash '+r.flashSize:'')],[t('Nodo / Control'),r.hostname+' · '+r.ctrlHost],[t('Estado arranque'),boot.booted?(boot.provisioned_from_nvs?t('Arrancado · NVS init_json aplicado'):t('Arrancado')):t('Grabado (sin lectura serie)')],[t('IP Wi-Fi'),boot.wifi_ip||t('Pendiente de asociación')],[t('IP Tailnet'),boot.vpn_ip?(boot.vpn_ip+' ('+(boot.tailnet_state||'OK')+')'):(boot.tailnet_state||t('Pendiente de registro / aprobación'))]];if(r.backup?.path)rows.push([t('Respaldo previo'),r.backup.path]);$('iot-result-details').replaceChildren(...rows.map(([k,v])=>{const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;div.append(dt,dd);return div;}));$('iot-result-token').textContent=r.apiToken||'';}

